# Autotune sweeps XBLOCK in {1,16}, YBLOCK in {32..1024}
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1,  'YBLOCK': 1024}, num_warps=16),
        triton.Config({'XBLOCK': 16, 'YBLOCK': 256},  num_warps=8),
        # ... more configs
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(in_ptr, out_ptr, ynumel, xnumel, YBLOCK: tl.constexpr, XBLOCK: tl.constexpr):
    xnumel = 9
    ynumel = 6144
    ...

# NOTE: grid was NOT updated to lambda meta — this limited the benefit
grid = (cdiv(9, 128), cdiv(6144, 8))  # still (1, 768)
kernel[grid](arg0, arg1, 6144, 9)  # autotune selects XBLOCK/YBLOCK

